//! Verifies real snarkjs proofs (generated by circuits/scripts/prove-fixture.mjs)
//! with the exact code path the on-chain program uses. This pins down the proof
//! byte encoding (negated A, G2 limb order) and the public-input order.

use scash_vault::verifier;

#[derive(serde::Deserialize)]
struct Fixture {
    proof: String,
    public_inputs: Vec<String>,
}

#[derive(serde::Deserialize)]
struct File {
    shield: Fixture,
    spend: Fixture,
}

fn load() -> File {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/transact2x2.json");
    let s = std::fs::read_to_string(path).expect("fixture missing; run `node circuits/scripts/prove-fixture.mjs`");
    serde_json::from_str(&s).unwrap()
}

fn inputs(f: &Fixture) -> Vec<[u8; 32]> {
    f.public_inputs
        .iter()
        .map(|h| hex::decode(h).unwrap().try_into().unwrap())
        .collect()
}

#[test]
fn shield_proof_verifies() {
    let f = load();
    let proof = hex::decode(&f.shield.proof).unwrap();
    let pi = inputs(&f.shield);
    assert_eq!(pi.len(), 9);
    verifier::verify(2, &proof, &pi).expect("shield proof should verify");
}

#[test]
fn spend_proof_verifies_and_tampering_fails() {
    let f = load();
    let proof = hex::decode(&f.spend.proof).unwrap();
    let mut pi = inputs(&f.spend);
    verifier::verify(2, &proof, &pi).expect("spend proof should verify");

    // flip one byte of ext_data_hash
    pi[3][31] ^= 1;
    assert!(verifier::verify(2, &proof, &pi).is_err());
}
